import{_ as a,C as r,o as s,c as n,E as o,a2 as i}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"After the Queue Entry Disappears: Who Can Prove the Work Still Exists?","description":"","frontmatter":{"title":"After the Queue Entry Disappears: Who Can Prove the Work Still Exists?","date":"2026-08-12","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"When queued intent is removed after Core acceptance rather than after persistence, what execution-authority and recovery boundary should a durable agent runtime expose?","summary":"Queue deletion can establish that the execution layer took custody; it cannot also establish that recovery evidence was persisted. The missing design object is a reconstructable handoff between those facts.","sources":"https://github.com/openai/codex/commit/da2803c73cd366b5e01ffe8d0e5f7d396247f827; research/analysis/Q-20260812-01-acceptance-persistence-handoff.md; research/reading/Q-20260812-01-acceptance-based-queued-work-admission.md","item_id":"Q-20260812-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-12-acceptance-persistence-handoff.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-12-acceptance-persistence-handoff.md","filePath":"en/digital-employee/2026-08-12-acceptance-persistence-handoff.md","lastUpdated":1786537067000}'),c={name:"en/digital-employee/2026-08-12-acceptance-persistence-handoff.md"};function d(l,e,h,u,p,f){const t=r("ArticleCover");return s(),n("div",null,[o(t,{image:"/assets/covers/daily-2026-08-12-acceptance-persistence-handoff.png",kicker:"Digital Employee · Daily Research",title:"After the Queue Entry Disappears: Who Can Prove the Work Still Exists?",summary:"Queue deletion can establish that the execution layer took custody; it cannot also establish that recovery evidence was persisted. The missing design object is a reconstructable handoff between those facts.",version:"Q-20260812-01",status:"Daily Runtime V5 · 2026-08-12",languageHref:"/zh/digital-employee/2026-08-12-acceptance-persistence-handoff",languageLabel:"中文"}),e[0]||(e[0]=i('<h1 id="after-the-queue-entry-disappears-who-can-prove-the-work-still-exists" tabindex="-1">After the Queue Entry Disappears: Who Can Prove the Work Still Exists? <a class="header-anchor" href="#after-the-queue-entry-disappears-who-can-prove-the-work-still-exists" aria-label="Permalink to &quot;After the Queue Entry Disappears: Who Can Prove the Work Still Exists?&quot;">​</a></h1><p>A queued input is accepted by Core and immediately removed from the queue. A few milliseconds later, the process crashes.</p><p>After restart, the queue is empty, no later durable record exists, and the client knows only that its request timed out. The hardest question is not yet whether to retry. It is more basic: <strong>what surviving fact proves who took custody of this work?</strong></p><p>That is the gap hidden when acceptance and persistence are compressed into one status. The selected <a href="https://github.com/openai/codex/commit/da2803c73cd366b5e01ffe8d0e5f7d396247f827" target="_blank" rel="noreferrer">OpenAI Codex change</a> supports two narrow facts: queued input is admitted when Core accepts it, and the Queue Entry is then deleted. It does not establish restart-safe exactly-once processing or rollback for arbitrary external effects.</p><h2 id="cut-the-path-at-three-failure-points" tabindex="-1">Cut the path at three failure points <a class="header-anchor" href="#cut-the-path-at-three-failure-points" aria-label="Permalink to &quot;Cut the path at three failure points&quot;">​</a></h2><p>Start with a crash rather than a vocabulary of states:</p><table tabindex="0"><thead><tr><th>Moment</th><th>What is established</th><th>What is not established</th></tr></thead><tbody><tr><td>Queue Entry still exists</td><td>The system retains demand for execution</td><td>No execution owner has necessarily accepted responsibility</td></tr><tr><td>Core accepted; Queue Entry deleted</td><td>Execution responsibility transferred</td><td>Restart-surviving execution evidence may not yet exist</td></tr><tr><td>A later record was persisted</td><td>At least one recovery or reconciliation fact can survive</td><td>End-to-end exactly-once still does not follow</td></tr></tbody></table><p>These moments are not percentages on a completion bar. They answer whether demand exists, whether responsibility transferred, and whether evidence survives failure. Calling the second row “completed” makes an empty queue carry a claim it cannot support.</p><h2 id="custody-transfers-correctness-does-not" tabindex="-1">Custody transfers; correctness does not <a class="header-anchor" href="#custody-transfers-correctness-does-not" aria-label="Permalink to &quot;Custody transfers; correctness does not&quot;">​</a></h2><p>Core acceptance draws a useful responsibility boundary. From that point, the client or upstream queue should no longer treat the work as unowned. Earlier acknowledgement may also reduce storage-coupled admission delay.</p><p>But custody is not correctness. A downstream hook can stop the work, the process can exit before a durable record is written, and an external operation can remain outcome-ambiguous. Recovery can no longer rely on the deleted Queue Entry, yet it cannot infer success from queue absence.</p><p>The important design object is therefore not another Boolean. It is a reconstructable <strong>work occurrence</strong>: who accepted it, which submission was accepted, the last verified event, and the evidence a successor must use.</p><h2 id="a-receipt-can-narrow-ambiguity-not-abolish-it" tabindex="-1">A receipt can narrow ambiguity, not abolish it <a class="header-anchor" href="#a-receipt-can-narrow-ambiguity-not-abolish-it" aria-label="Permalink to &quot;A receipt can narrow ambiguity, not abolish it&quot;">​</a></h2><p>One testable hypothesis is to persist an Accepted-occurrence Receipt, with stable occurrence identity, before or while destructive queue ownership is released.</p><p>Such a receipt can turn “the queue is empty and nothing is known” into “this occurrence was accepted and its later outcome requires reconciliation.” It can distinguish never accepted, accepted without later progress, durably recorded, and terminal work.</p><p>It cannot create exactly-once semantics by itself. A crash after an external effect but before terminal persistence still requires an idempotency key, an external read-back, or compensation. For naturally replayable work, the state cost of a receipt may exceed the ambiguity it removes. Earlier acceptance is not universally better than persistence-gated admission; they choose different latency, state, and recovery costs.</p><h2 id="how-this-design-should-be-falsified" tabindex="-1">How this design should be falsified <a class="header-anchor" href="#how-this-design-should-be-falsified" aria-label="Permalink to &quot;How this design should be falsified&quot;">​</a></h2><p>The next step is fault injection, not more status names. Terminate the process before Core acceptance, after queue deletion, around receipt persistence, and on both sides of an external effect. Then reconstruct the occurrence using only durable facts.</p><p>If recovery cannot distinguish never accepted from accepted-but-lost, the receipt is still written too late. If occurrence identity survives but the external effect remains unknowable, the missing contract is effect idempotency and read-back—not another queue state. If naturally replayable work recovers without ambiguity, the receipt should not become a universal requirement.</p><p>The bounded conclusion is deliberately falsifiable: <strong>execution acceptance may transfer custody, but a durable runtime needs separate surviving evidence that reconstructs that transfer; even that evidence does not prove the work ran only once.</strong></p><h3 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h3><ul><li><strong>What the source shows:</strong> the selected Codex implementation deletes the Queue Entry after Core admission. The public commit is checkable first-party evidence, not independent validation.</li><li><strong>What the source does not establish:</strong> restart-safe exactly-once behavior, global effect idempotency, and complete crash recovery remain unproven.</li><li><strong>What this article proposes testing:</strong> implement an Accepted-occurrence Receipt and use fault injection to determine whether it reduces recovery ambiguity.</li></ul><p><strong>References:</strong></p><ul><li>OpenAI Codex, 11 August 2026, <a href="https://github.com/openai/codex/commit/da2803c73cd366b5e01ffe8d0e5f7d396247f827" target="_blank" rel="noreferrer"><code>da2803c</code> — Simplify queued user message admission</a>, code commit with tests changed in the same commit boundary.</li></ul>',24))])}const b=a(c,[["render",d]]);export{y as __pageData,b as default};
